// Fetch week stats
const cfg = $json;
const weekAgo = new Date();
weekAgo.setDate(weekAgo.getDate() - 7);
const sinceISO = weekAgo.toISOString();

async function fetchCount(url) {
  const r = await this.helpers.httpRequest({
    method: 'GET', url, returnFullResponse: true, json: true,
    headers: {
      apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
      Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
      'Accept-Profile': 'purama_ai',
      Prefer: 'count=exact',
    },
  });
  return parseInt((r.headers['content-range'] || '0/0').split('/')[1] || '0', 10);
}

const base = 'https://auth.purama.dev/rest/v1';
const u = cfg.user_id;
const newProspects = await fetchCount.call(this, `${base}/partner_prospects?user_id=eq.${u}&created_at=gte.${sinceISO}&select=id`);
const sentEmails = await fetchCount.call(this, `${base}/partner_emails?user_id=eq.${u}&sent_at=gte.${sinceISO}&select=id`);
const replies = await fetchCount.call(this, `${base}/partner_emails?user_id=eq.${u}&replied=eq.true&replied_at=gte.${sinceISO}&select=id`);
const signed = await fetchCount.call(this, `${base}/partner_prospects?user_id=eq.${u}&contract_signed_at=gte.${sinceISO}&select=id`);
const activePartners = await fetchCount.call(this, `${base}/partner_active?user_id=eq.${u}&is_active=eq.true&select=id`);

const rate = sentEmails > 0 ? Math.round((replies / sentEmails) * 100) : 0;

return [{ json: {
  ...cfg,
  _stats: { newProspects, sentEmails, replies, signed, activePartners, rate },
} }];

const cfg = $json;
const s = cfg._stats;
const body = `Cette semaine: ${s.newProspects} nouveaux prospects · ${s.sentEmails} emails · ${s.replies} réponses (${s.rate}%) · ${s.signed} contrats signés · ${s.activePartners} partenaires actifs`;
return [{ json: {
  user_id: cfg.user_id,
  agent_type: 'partner',
  title: '🤝 Rapport partenariat hebdomadaire',
  body,
  action_type: 'review',
  action_url: '/dashboard/partner-agent',
  priority: 'normal',
  channels: ['push', 'in_app'],
} }];
